import{_ as t,o as e,c as r,a2 as l}from"./chunks/framework.Crpw6aS5.js";const d=JSON.parse('{"title":"雪莉·图米姆","description":"","frontmatter":{"title":"雪莉·图米姆","date":"2026-04-13T00:00:00.000Z"},"headers":[],"relativePath":"04_people/雪莉·图米姆.md","filePath":"04_people/雪莉·图米姆.md"}'),o={name:"04_people/雪莉·图米姆.md"};function i(n,a,s,_,h,p){return e(),r("div",null,[...a[0]||(a[0]=[l('<h1 id="雪莉·图米姆" tabindex="-1">雪莉·图米姆 <a class="header-anchor" href="#雪莉·图米姆" aria-label="Permalink to &quot;雪莉·图米姆&quot;">​</a></h1><ul><li><strong>角色职位</strong>：明星家具（Star Furniture）高管</li><li><strong>与巴菲特关系</strong>：被伯克希尔·哈撒韦收购的子公司管理层成员</li></ul><h2 id="主要事迹" tabindex="-1">主要事迹 <a class="header-anchor" href="#主要事迹" aria-label="Permalink to &quot;主要事迹&quot;">​</a></h2><p>雪莉·图米姆是明星家具（Star Furniture）的高管，在公司管理层中发挥重要作用。明星家具由梅尔文·沃尔夫创立，是美国中南部地区极具影响力的家具零售商，以可靠的品质和亲民的价格赢得了当地消费者的口碑。作为公司高管，图米姆深度参与了明星家具的日常运营管理。</p><p>在伯克希尔收购明星家具后，公司保持了原有的管理团队和运营文化。雪莉·图米姆与其他管理层成员共同确保了收购过渡期的平稳衔接，使明星家具在伯克希尔的控股结构下继续稳健发展。这种&quot;放手式&quot;的管理风格正是巴菲特收购优质企业后一贯坚持的做法。</p><p>图米姆在明星家具的角色体现了伯克希尔一贯看重的特质——经验丰富的本地管理团队，对当地市场有深刻理解，并致力于为客户提供长期价值。明星家具能够在竞争激烈的零售市场中保持竞争力，离不开图米姆等管理层的专业付出。</p><h2 id="关键年份事件" tabindex="-1">关键年份事件 <a class="header-anchor" href="#关键年份事件" aria-label="Permalink to &quot;关键年份事件&quot;">​</a></h2><ul><li><strong>管理层任职</strong>：作为明星家具高管，长期负责公司核心业务的管理工作</li><li><strong>收购过渡期</strong>：在伯克希尔收购明星家具期间，与创始人沃尔夫等管理团队共同推进平稳过渡</li><li><strong>持续经营期</strong>：在伯克希尔控股下继续运营，为公司保持区域市场领先地位做出贡献</li></ul><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>以下为该人物在致股东信中被提及的关键年份，点击即可阅读完整翻译：</p><ul><li><a href="/search.html?q=雪莉·图米姆在1999年股东信中的原话">1999年：完整翻译|/01_letters/1999年/翻译</a></li></ul>',11)])])}const c=t(o,[["render",i]]);export{d as __pageData,c as default};
